    /// <summary>
    /// Story 5: Mark a received donation as completed.
    /// Authorized for Donor (DonorId) or Organization (OrganizationId) associated with the donation.
    /// </summary>
    [HttpPost("{id:int}/complete")]
    [ProducesResponseType(typeof(ApiResponse<DeliveryTrackingResponseDto>), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ApiResponse<DeliveryTrackingResponseDto>), StatusCodes.Status400BadRequest)]
    [ProducesResponseType(StatusCodes.Status403Forbidden)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> CompleteDonation(int id, [FromBody] CompleteDonationDto? dto = null)
    {
        var (userId, userRole) = GetCallerIdentity();

        var arrangement = await _context.DeliveryArrangements
            .AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == id);

        if (arrangement == null)
        {
            return NotFound(ApiResponse<DeliveryTrackingResponseDto>.Fail($"Delivery arrangement with ID {id} not found."));
        }

        // Strict Authorization Check (Story 5: Donor or Organization ONLY)
        if (userId != arrangement.DonorId && userId != arrangement.OrganizationId)
        {
            return StatusCode(StatusCodes.Status403Forbidden,
                ApiResponse<DeliveryTrackingResponseDto>.Fail("You are not authorized to mark this donation as complete."));
        }

        // Duplicate Check using exact stored string
        if (arrangement.Status == "Completed")
        {
            return BadRequest(ApiResponse<DeliveryTrackingResponseDto>.Fail("Donation lifecycle has already been completed."));
        }

        // Invalid Transition Check using exact stored string
        if (arrangement.Status != "Received")
        {
            return BadRequest(ApiResponse<DeliveryTrackingResponseDto>.Fail(
                $"Cannot complete donation. Current status is '{arrangement.Status}', but must be 'Received'."));
        }

        // Atomic Concurrency Guard, History & Notifications inside a single Database Transaction
        using var transaction = await _context.Database.BeginTransactionAsync();
        try
        {
            var now = DateTime.UtcNow;
            var previousStatus = arrangement.Status;

            // Conditional update at database execution level checking exact status "Received"
            var updatedRows = await _context.DeliveryArrangements
                .Where(d => d.Id == id && d.Status == "Received")
                .ExecuteUpdateAsync(s => s
                    .SetProperty(d => d.Status, "Completed")
                    .SetProperty(d => d.CompletedAt, now)
                    .SetProperty(d => d.UpdatedAt, now));

            if (updatedRows == 0)
            {
                await transaction.RollbackAsync();
                return BadRequest(ApiResponse<DeliveryTrackingResponseDto>.Fail(
                    "Action rejected. The donation status has already been updated or modified concurrently."));
            }

            // Insert status history entry
            var history = new DeliveryStatusHistory
            {
                DeliveryArrangementId = arrangement.Id,
                PreviousStatus = previousStatus,
                NewStatus = "Completed",
                ChangedByUserId = userId,
                ChangedByRole = userRole,
                Notes = dto?.Notes?.Trim(),
                Timestamp = now
            };
            _context.DeliveryStatusHistories.Add(history);

            // Add Notifications for Donor and Organization within the same transaction
            var notifMsg = $"Donation lifecycle for '{arrangement.DonationTitle}' has been successfully completed!";
            AddNotificationIfUnique(arrangement.DonorId, "Donation Completed", notifMsg, "DONATION_COMPLETED", arrangement.Id, now);
            AddNotificationIfUnique(arrangement.OrganizationId, "Donation Completed", notifMsg, "DONATION_COMPLETED", arrangement.Id, now);

            // Synchronize completion state to Requests table in database if present
            try
            {
                await _context.Database.ExecuteSqlRawAsync(
                    "UPDATE \"Requests\" SET \"Status\" = 'COMPLETED' WHERE \"Id\" = {0}",
                    arrangement.RequestId);
            }
            catch (Exception syncEx)
            {
                _logger.LogWarning(syncEx, "Optional Requests table sync to COMPLETED skipped for RequestId {RequestId}", arrangement.RequestId);
            }

            // Synchronize completion state to DonorOffers table in database if present
            try
            {
                await _context.Database.ExecuteSqlRawAsync(
                    "UPDATE \"DonorOffers\" SET \"Status\" = 'COMPLETED' WHERE \"Id\" = {0}",
                    arrangement.RequestId);
            }
            catch (Exception syncEx)
            {
                _logger.LogWarning(syncEx, "Optional DonorOffers table sync to COMPLETED skipped for RequestId {RequestId}", arrangement.RequestId);
            }

            await _context.SaveChangesAsync();
            await transaction.CommitAsync();

            _logger.LogInformation("User {UserId} completed donation lifecycle for Delivery {DeliveryId}", userId, arrangement.Id);

            // Fetch fresh database row bypassing EF change tracker cache
            var updatedArrangement = await _context.DeliveryArrangements
                .AsNoTracking()
                .Include(d => d.History)
                .FirstOrDefaultAsync(d => d.Id == id);

            return Ok(ApiResponse<DeliveryTrackingResponseDto>.Ok(MapToDto(updatedArrangement!), "Donation lifecycle completed successfully."));
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync();
            _logger.LogError(ex, "Error completing donation lifecycle for delivery {DeliveryId}", id);
            return StatusCode(StatusCodes.Status500InternalServerError,
                ApiResponse<DeliveryTrackingResponseDto>.Fail("An internal error occurred while completing donation."));
        }
    }

    /// <summary>
    /// Admin monitoring endpoint exposing complete delivery logistics metrics.
    /// </summary>
    [HttpGet("admin/summary")]
    [Authorize(Roles = "ADMIN")]
    [ProducesResponseType(typeof(ApiResponse<object>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetAdminDeliverySummary()
    {
        var allDeliveries = await _context.DeliveryArrangements.ToListAsync();
        var totalCount = allDeliveries.Count;
        var arrangedCount = allDeliveries.Count(d => d.Status == "CollectionArranged");
        var collectedCount = allDeliveries.Count(d => d.Status == "FoodCollected");
        var receivedCount = allDeliveries.Count(d => d.Status == "FoodReceived");
        var completedCount = allDeliveries.Count(d => d.Status == "Completed");
        var cancelledCount = allDeliveries.Count(d => d.Status == "Cancelled");

        var summary = new
        {
            totalCount,
            arrangedCount,
            collectedCount,
            receivedCount,
            completedCount,
            cancelledCount,
            recentDeliveries = allDeliveries.OrderByDescending(d => d.CreatedAt).Take(10).Select(MapToDto)
        };

        return Ok(ApiResponse<object>.Ok(summary, "Admin delivery monitoring summary retrieved."));
    }

    private void AddNotificationIfUnique(string recipientUserId, string title, string message, string type, int relatedId, DateTime createdAt)
    {
        if (string.IsNullOrWhiteSpace(recipientUserId)) return;

        // Check local change tracker or db to prevent duplicate notification entry in the same transaction
        if (!_context.DeliveryNotifications.Local.Any(n => n.UserId == recipientUserId && n.Type == type && n.RelatedId == relatedId))
        {
            _context.DeliveryNotifications.Add(new DeliveryNotification
            {
                UserId = recipientUserId,
                Title = title,
                Message = message,
                Type = type,
                RelatedId = relatedId,
                IsRead = false,
                CreatedAt = createdAt
            });
        }
    }

    private (string userId, string role) GetCallerIdentity()
    {
        var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value
            ?? User.FindFirst("id")?.Value
            ?? User.FindFirst("sub")?.Value
            ?? User.FindFirst("http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier")?.Value
            ?? string.Empty;

        var role = User.FindFirst(ClaimTypes.Role)?.Value
            ?? User.FindFirst("role")?.Value
            ?? "USER";

        return (userId, role);
    }

    private async Task<VerifiedRequestInfo?> VerifyRequestAcceptanceAsync(int requestId)
    {
        // 1. Check Requests table (Surplus food listing requests)
        try
        {
            using var command = _context.Database.GetDbConnection().CreateCommand();
            command.CommandText = @"
                SELECT ""Id"", ""DonationId"", ""DonationTitle"", ""OrganizationId"", ""OrganizationName"", ""DonorId"", ""Status""
                FROM ""Requests""
                WHERE ""Id"" = @reqId";

            var param = command.CreateParameter();
            param.ParameterName = "@reqId";
            param.Value = requestId;
            command.Parameters.Add(param);

            if (command.Connection?.State != System.Data.ConnectionState.Open)
            {
                await _context.Database.OpenConnectionAsync();
            }

            using var reader = await command.ExecuteReaderAsync();
            if (await reader.ReadAsync())
            {
                return new VerifiedRequestInfo
                {
                    Id = reader.GetInt32(0),
                    DonationId = reader.GetInt32(1),
                    DonationTitle = reader.IsDBNull(2) ? "" : reader.GetString(2),
                    OrganizationId = reader.IsDBNull(3) ? "" : reader.GetString(3),
                    OrganizationName = reader.IsDBNull(4) ? "" : reader.GetString(4),
                    DonorId = reader.IsDBNull(5) ? "" : reader.GetString(5),
                    DonorName = "Donor User",
                    Status = reader.IsDBNull(6) ? "PENDING" : reader.GetString(6)
                };
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error verifying acceptance for food request {RequestId}", requestId);
        }

        // 2. Check DonorOffers table (Organization food need requests with donor offers)
        try
        {
            using var command = _context.Database.GetDbConnection().CreateCommand();
            command.CommandText = @"
                SELECT o.""Id"", o.""OrgFoodNeedRequestId"", o.""OrgFoodNeedRequestTitle"", r.""OrganizationId"", r.""OrganizationName"", o.""DonorId"", o.""DonorName"", o.""Status""
                FROM ""DonorOffers"" o
                JOIN ""OrgNeedRequests"" r ON o.""OrgFoodNeedRequestId"" = r.""Id""
                WHERE o.""Id"" = @reqId";

            var param = command.CreateParameter();
            param.ParameterName = "@reqId";
            param.Value = requestId;
            command.Parameters.Add(param);

            if (command.Connection?.State != System.Data.ConnectionState.Open)
            {
                await _context.Database.OpenConnectionAsync();
            }

            using var reader = await command.ExecuteReaderAsync();
            if (await reader.ReadAsync())
            {
                return new VerifiedRequestInfo
                {
                    Id = reader.GetInt32(0),
                    DonationId = reader.GetInt32(1),
                    DonationTitle = reader.IsDBNull(2) ? "" : reader.GetString(2),
                    OrganizationId = reader.IsDBNull(3) ? "" : reader.GetString(3),
                    OrganizationName = reader.IsDBNull(4) ? "" : reader.GetString(4),
                    DonorId = reader.IsDBNull(5) ? "" : reader.GetString(5),
                    DonorName = reader.IsDBNull(6) ? "Donor User" : reader.GetString(6),
                    Status = reader.IsDBNull(7) ? "PENDING" : reader.GetString(7)
                };
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error verifying acceptance for donor offer {RequestId}", requestId);
        }

        return null;
    }

    private static DeliveryTrackingResponseDto MapToDto(DeliveryArrangement d)
    {
        return new DeliveryTrackingResponseDto
        {
            Id = d.Id,
            RequestId = d.RequestId,
            DonationId = d.DonationId,
            DonationTitle = d.DonationTitle,
            DonorId = d.DonorId,
            DonorName = d.DonorName,
            OrganizationId = d.OrganizationId,
            OrganizationName = d.OrganizationName,
            PickupAddress = d.PickupAddress,
            DeliveryAddress = d.DeliveryAddress,
            ContactName = d.ContactName,
            ContactPhone = d.ContactPhone,
            ScheduledCollectionTime = d.ScheduledCollectionTime,
            Notes = d.Notes,
            Status = d.Status,
            ArrangedAt = d.ArrangedAt,
            CollectedAt = d.CollectedAt,
            ReceivedAt = d.ReceivedAt,
            CompletedAt = d.CompletedAt,
            CreatedAt = d.CreatedAt,
            UpdatedAt = d.UpdatedAt,
            StatusHistory = d.History
                .OrderBy(h => h.Timestamp)
                .Select(h => new DeliveryStatusHistoryDto
                {
                    Id = h.Id,
                    DeliveryArrangementId = h.DeliveryArrangementId,
                    PreviousStatus = h.PreviousStatus,
                    NewStatus = h.NewStatus,
                    ChangedByUserId = h.ChangedByUserId,
                    ChangedByRole = h.ChangedByRole,
                    Notes = h.Notes,
                    Timestamp = h.Timestamp
                }).ToList()
        };
    }

    private class VerifiedRequestInfo
    {
        public int Id { get; set; }
        public int DonationId { get; set; }
        public string DonationTitle { get; set; } = string.Empty;
        public string OrganizationId { get; set; } = string.Empty;
        public string OrganizationName { get; set; } = string.Empty;
        public string DonorId { get; set; } = string.Empty;
        public string DonorName { get; set; } = string.Empty;
        public string Status { get; set; } = string.Empty;
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using DeliveryWorkflowService.Data;
using DeliveryWorkflowService.DTOs;
using DeliveryWorkflowService.Models;

namespace DeliveryWorkflowService.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class NotificationsController : ControllerBase
{
    private readonly DeliveryDbContext _context;
    private readonly ILogger<NotificationsController> _logger;

    public NotificationsController(DeliveryDbContext context, ILogger<NotificationsController> logger)
    {
        _context = context;
        _logger = logger;
    }

    /// <summary>
    /// Gets all delivery notifications for the authenticated caller.
    /// </summary>
    [HttpGet]
    [ProducesResponseType(typeof(ApiResponse<List<DeliveryNotificationResponseDto>>), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> GetMyNotifications()
    {
        var userId = GetCallerUserId();
        if (string.IsNullOrWhiteSpace(userId))
        {
            return Unauthorized(ApiResponse<List<DeliveryNotificationResponseDto>>.Fail("Authentication claims missing."));
        }

        var notifications = await _context.DeliveryNotifications
            .AsNoTracking()
            .Where(n => n.UserId == userId)
            .OrderByDescending(n => n.CreatedAt)
            .Take(50)
            .Select(n => new DeliveryNotificationResponseDto
            {
                Id = n.Id,
                UserId = n.UserId,
                Title = n.Title,
                Message = n.Message,
                Type = n.Type,
                IsRead = n.IsRead,
                RelatedId = n.RelatedId,
                CreatedAt = n.CreatedAt
            })
            .ToListAsync();

        return Ok(ApiResponse<List<DeliveryNotificationResponseDto>>.Ok(notifications));
    }

    /// <summary>
    /// Marks a single notification as read for the authenticated caller.
    /// </summary>
    [HttpPatch("{id:int}/read")]
    [ProducesResponseType(typeof(ApiResponse<string>), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> MarkAsRead(int id)
    {
        var userId = GetCallerUserId();
        var notification = await _context.DeliveryNotifications
            .FirstOrDefaultAsync(n => n.Id == id && n.UserId == userId);

        if (notification == null)
        {
            return NotFound(ApiResponse<string>.Fail("Notification not found."));
        }

        notification.IsRead = true;
        await _context.SaveChangesAsync();
        return Ok(ApiResponse<string>.Ok("Marked notification as read."));
    }

    /// <summary>
    /// Marks all unread notifications for the authenticated caller as read.
    /// </summary>
    [HttpPatch("read-all")]
    [ProducesResponseType(typeof(ApiResponse<string>), StatusCodes.Status200OK)]
    public async Task<IActionResult> MarkAllAsRead()
    {
        var userId = GetCallerUserId();
        var unread = await _context.DeliveryNotifications
            .Where(n => n.UserId == userId && !n.IsRead)
            .ToListAsync();

        foreach (var n in unread)
        {
            n.IsRead = true;
        }

        await _context.SaveChangesAsync();
        return Ok(ApiResponse<string>.Ok("All delivery notifications marked as read."));
    }

    /// <summary>
    /// Clears/deletes all read notifications for the authenticated caller.
    /// </summary>
    [HttpDelete("clear-read")]
    [ProducesResponseType(typeof(ApiResponse<string>), StatusCodes.Status200OK)]
    public async Task<IActionResult> ClearReadNotifications()
    {
        var userId = GetCallerUserId();
        var readNotifs = await _context.DeliveryNotifications
            .Where(n => n.UserId == userId && n.IsRead)
            .ToListAsync();

        _context.DeliveryNotifications.RemoveRange(readNotifs);
        await _context.SaveChangesAsync();
        return Ok(ApiResponse<string>.Ok("Cleared read delivery notifications."));
    }

    private string GetCallerUserId()
    {
        var userIdClaim = User.FindFirst(ClaimTypes.NameIdentifier)?.Value
            ?? User.FindFirst("id")?.Value
            ?? User.FindFirst("sub")?.Value
            ?? User.FindFirst("http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier")?.Value;

        return userIdClaim ?? string.Empty;
    }
}

using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using Microsoft.OpenApi.Models;
using DeliveryWorkflowService.Data;

var builder = WebApplication.CreateBuilder(args);

// 1. Database Configuration (PostgreSQL - RescuePlateDB via Npgsql EF Core)
var connectionString = builder.Configuration.GetConnectionString("PostgreSQLConnection")
    ?? builder.Configuration["ConnectionStrings__PostgreSQLConnection"]
    ?? "Host=localhost;Port=5432;Database=RescuePlateDB;Username=postgres;Password=postgres";

builder.Services.AddDbContext<DeliveryDbContext>(options =>
{
    options.UseNpgsql(connectionString);
});

// 2. Health Checks Registration
builder.Services.AddHealthChecks()
    .AddDbContextCheck<DeliveryDbContext>(
        name: "PostgreSQL",
        tags: new[] { "db", "data" });

// 3. JWT Authentication & Authorization Setup
var secretKey = builder.Configuration["Jwt:SecretKey"]
    ?? builder.Configuration["JWT_SECRET_KEY"];

if (string.IsNullOrWhiteSpace(secretKey))
{
    // Fallback for development local execution if not injected via env
    secretKey = "RescuePlate_Super_Secret_Key_For_Jwt_Authentication_2026_Sprint1_RescueFood";
}

var issuer = builder.Configuration["Jwt:Issuer"] ?? "RescuePlate.UserService";
var audience = builder.Configuration["Jwt:Audience"] ?? "RescuePlate.Client";
var frontendUrl = builder.Configuration["FrontendUrl"] ?? "http://localhost:5173";

builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.RequireHttpsMetadata = false;
        options.SaveToken = true;
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = issuer,
            ValidAudience = audience,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
            RoleClaimType = ClaimTypes.Role,
            NameClaimType = ClaimTypes.NameIdentifier,
            ClockSkew = TimeSpan.Zero
        };
    });

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("DonorOnly", policy => policy.RequireRole("DONOR"));
    options.AddPolicy("OrganizationOnly", policy => policy.RequireRole("ORGANIZATION"));
    options.AddPolicy("AdminOnly", policy => policy.RequireRole("ADMIN"));
});

// 4. CORS Policy Setup
builder.Services.AddCors(options =>
{
    options.AddPolicy("AllowFrontend", policy =>
    {
        policy.WithOrigins(frontendUrl, "http://localhost:3000")
              .AllowAnyHeader()
              .AllowAnyMethod()
              .AllowCredentials();
    });
});

// 5. Controllers & JSON Serialization Options
builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.ReferenceHandler = System.Text.Json.Serialization.ReferenceHandler.IgnoreCycles;
        options.JsonSerializerOptions.Converters.Add(new System.Text.Json.Serialization.JsonStringEnumConverter());
    });

// 6. Swagger / OpenAPI Documentation
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "RescuePlate Delivery Workflow Service API",
        Version = "v1",
        Description = "ASP.NET Core 10 Microservice for managing tracking, delivery collection, and notifications (Sprint 4 & 5)"
    });

    options.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
    {
        Description = "JWT Authorization header using the Bearer scheme. Example: \"Authorization: Bearer {token}\"",
        Name = "Authorization",
        In = ParameterLocation.Header,
        Type = SecuritySchemeType.ApiKey,
        Scheme = "Bearer"
    });

    options.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme
            {
                Reference = new OpenApiReference
                {
                    Type = ReferenceType.SecurityScheme,
                    Id = "Bearer"
                }
            },
            Array.Empty<string>()
        }
    });
});

var app = builder.Build();

// 7. Automatic Database Table Initialization & Schema Setup
using (var scope = app.Services.CreateScope())
{
    var dbContext = scope.ServiceProvider.GetRequiredService<DeliveryDbContext>();
    try
    {
        dbContext.Database.ExecuteSqlRaw(@"
            CREATE TABLE IF NOT EXISTS ""DeliveryArrangements"" (
                ""Id"" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                ""RequestId"" integer NOT NULL,
                ""DonationId"" integer NOT NULL,
                ""DonationTitle"" character varying(200) NOT NULL DEFAULT '',
                ""DonorId"" character varying(100) NOT NULL,
                ""DonorName"" character varying(150) NOT NULL,
                ""OrganizationId"" character varying(100) NOT NULL,
                ""OrganizationName"" character varying(150) NOT NULL,
                ""PickupAddress"" character varying(255) NOT NULL,
                ""DeliveryAddress"" character varying(255) NOT NULL,
                ""ContactName"" character varying(150) NOT NULL,
                ""ContactPhone"" character varying(50) NOT NULL,
                ""ScheduledCollectionTime"" timestamp with time zone NOT NULL,
                ""Notes"" character varying(500),
                ""Status"" character varying(50) NOT NULL DEFAULT 'CollectionArranged',
                ""ArrangedAt"" timestamp with time zone NOT NULL,
                ""CollectedAt"" timestamp with time zone,
                ""ReceivedAt"" timestamp with time zone,
                ""CompletedAt"" timestamp with time zone,
                ""CreatedAt"" timestamp with time zone NOT NULL,
                ""UpdatedAt"" timestamp with time zone
            );

            CREATE UNIQUE INDEX IF NOT EXISTS ""IX_DeliveryArrangements_RequestId"" ON ""DeliveryArrangements"" (""RequestId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryArrangements_DonationId"" ON ""DeliveryArrangements"" (""DonationId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryArrangements_DonorId"" ON ""DeliveryArrangements"" (""DonorId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryArrangements_OrganizationId"" ON ""DeliveryArrangements"" (""OrganizationId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryArrangements_Status"" ON ""DeliveryArrangements"" (""Status"");

            CREATE TABLE IF NOT EXISTS ""DeliveryStatusHistories"" (
                ""Id"" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                ""DeliveryArrangementId"" integer NOT NULL,
                ""PreviousStatus"" character varying(50) NOT NULL,
                ""NewStatus"" character varying(50) NOT NULL,
                ""ChangedByUserId"" character varying(100) NOT NULL,
                ""ChangedByRole"" character varying(50) NOT NULL,
                ""Notes"" character varying(500),
                ""Timestamp"" timestamp with time zone NOT NULL
            );

            CREATE INDEX IF NOT EXISTS ""IX_DeliveryStatusHistories_DeliveryArrangementId"" ON ""DeliveryStatusHistories"" (""DeliveryArrangementId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryStatusHistories_Timestamp"" ON ""DeliveryStatusHistories"" (""Timestamp"");

            CREATE TABLE IF NOT EXISTS ""DeliveryNotifications"" (
                ""Id"" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                ""UserId"" character varying(100) NOT NULL,
                ""Title"" character varying(200) NOT NULL,
                ""Message"" character varying(1000) NOT NULL,
                ""Type"" character varying(50) NOT NULL,
                ""IsRead"" boolean NOT NULL DEFAULT FALSE,
                ""RelatedId"" integer NOT NULL,
                ""CreatedAt"" timestamp with time zone NOT NULL
            );

            CREATE UNIQUE INDEX IF NOT EXISTS ""IX_DeliveryNotifications_UserId_Type_RelatedId"" ON ""DeliveryNotifications"" (""UserId"", ""Type"", ""RelatedId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryNotifications_UserId"" ON ""DeliveryNotifications"" (""UserId"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryNotifications_IsRead"" ON ""DeliveryNotifications"" (""IsRead"");
            CREATE INDEX IF NOT EXISTS ""IX_DeliveryNotifications_CreatedAt"" ON ""DeliveryNotifications"" (""CreatedAt"");
        ");
    }
    catch (Exception ex)
    {
        var logger = scope.ServiceProvider.GetRequiredService<ILogger<Program>>();
        logger.LogWarning(ex, "Could not initialize DeliveryWorkflowService database schema.");
    }
}

// 8. Middleware Pipeline Setup
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI(c =>
    {
        c.SwaggerEndpoint("/swagger/v1/swagger.json", "RescuePlate Delivery Workflow Service API v1");
    });
}

app.UseCors("AllowFrontend");

app.UseAuthentication();
app.UseAuthorization();

// Health Check Endpoint mapping
app.MapHealthChecks("/health");

app.MapControllers();

app.Run();

