            ReceivedAt = status == "Received" || status == "Completed" ? DateTime.UtcNow.AddHours(-1) : null,
            CreatedAt = DateTime.UtcNow.AddHours(-3)
        };

        db.DeliveryArrangements.Add(arrangement);
        await db.SaveChangesAsync();
        db.ChangeTracker.Clear();
        return arrangement;
