            // Verify ONLY Donor notification of type RECEIPT_CONFIRMED is created
            var notifications = await db.DeliveryNotifications.Where(n => n.RelatedId == arrangement.Id && n.Type == "RECEIPT_CONFIRMED").ToListAsync();
